/**
 * Stored Google Routes API (v2) responses.
 *
 * These are FIXTURES used to prove that the numbers we display are produced by
 * Google's own fields — `distanceMeters`, `duration`, `staticDuration` and
 * `polyline.encodedPolyline` — and not by any local approximation.
 *
 * HOW THEY ARE USED (requirement 2.6):
 *   • For static fixtures we assert EXACT agreement with the stored response.
 *   • Live reruns against the real API are allowed to differ (traffic, route
 *     selection, map updates, departure time). See tests/travel-live.mjs.
 *
 * HONESTY NOTE: the sandbox that produced this codebase has no outbound network
 * access, so these payloads are structurally exact copies of the documented
 * Routes API v2 response shape with representative Indian road distances. They
 * are fixtures, NOT captured production traffic. `tests/travel-live.test.ts`
 * skips itself unless GOOGLE_MAPS_API_KEY is present, and that is the test that
 * must be used to validate real-world values before release.
 */

export interface FixtureRoute {
  distanceMeters: number;
  duration: string;
  staticDuration: string;
  polyline: { encodedPolyline: string };
  routeLabels?: string[];
  description?: string;
}

export interface RoutesFixture {
  /** Human explanation of the scenario. */
  scenario: string;
  origin: { lat: number; lng: number; label: string };
  destination: { lat: number; lng: number; hospitalId: string };
  /** Expected values derived from the payload by hand, to catch parser drift. */
  expected: {
    distanceMeters: number;
    distanceKm: number;
    durationSeconds: number;
    staticDurationSeconds: number;
    etaMinutes: number;
    staticMinutes: number;
    trafficImpactMinutes: number;
  };
  response: { routes: FixtureRoute[] };
}

/**
 * Encoded polylines below were generated by the standard Google polyline
 * algorithm (precision 1e5) for the listed coordinate pairs, so decoding them
 * round-trips to the stated points.
 */
