const POLY_PUSA_TO_AIIMS =
  'ggymDg`bvMv[od@ni@c`@~f@{Yrl@cVbo@cVzr@oUju@{Ozr@cGzr@nPj\\fJnZbG';

const POLY_NOIDA_TO_SAFDARJUNG =
  '{idmDwljwMsg@v|Aoi@vaBoi@f_B_g@r~Ao_@z_BwVz_BsN~bBcGzdB~Cf_BnPn`BvLzzAfOfpA';

const POLY_GURUGRAM_TO_AIIMS =
  '{nulDggcuMcy@gsBwy@gnBk_AklBk_AsmB_`AgnBk_AgnBk_AsmB_`AsmBcy@{dB_q@_jA_{@gfA';

